package tv.plus.pro.unified;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.hardware.usb.*;import android.view.*;import android.widget.*;import java.util.*;
public class DesktopModeActivity extends Activity {
 LinearLayout desktop,devices; TextView status;
 int dp(int x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
 GradientDrawable bg(int a,int b){GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{a,b});d.setCornerRadius(dp(18));return d;}
 TextView button(String title,LinearLayout parent,Runnable run){TextView v=new TextView(this);v.setText(title);v.setTextSize(15);v.setTextColor(Color.WHITE);v.setPadding(dp(18),dp(15),dp(18),dp(15));v.setBackground(bg(0xff263b77,0xff38215f));v.setFocusable(true);v.setOnClickListener(w->run.run());LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(6),0,dp(6));parent.addView(v,lp);return v;}
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().getDecorView().setSystemUiVisibility(5894|1024|512);getWindow().setFlags(1024,1024);desktop=new LinearLayout(this);desktop.setOrientation(1);desktop.setPadding(dp(20),dp(16),dp(20),dp(16));desktop.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff060d20,0xff173b72,0xff25104b}));ScrollView scroll=new ScrollView(this);scroll.addView(desktop);setContentView(scroll);TextView title=new TextView(this);title.setText("◈  TV+ Desktop   •   USB Workspace");title.setTextSize(24);title.setTextColor(-1);title.setTypeface(null,1);desktop.addView(title);status=new TextView(this);status.setTextColor(0xffd4d9ff);status.setTextSize(13);status.setPadding(0,dp(10),0,dp(12));desktop.addView(status);button("⟵  TV+ Ana Ekranına Dön",desktop,()->finish());button("↻  USB Aygıtlarını Yenile",desktop,()->refresh());button("▣  USB / Disk Dosyalarını Aç",desktop,()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);try{startActivityForResult(i,30);}catch(Exception e){message("Klasör seçici kullanılamıyor: "+e.getMessage());}});button("⌨  Klavye ve Fare Bilgisi",desktop,()->message("Bağlı klavye ve fare bu Android masaüstü arayüzünü kontrol eder. Tam giriş devri ancak gerçek bir VM motoru ve Android'in izin verdiği giriş yöntemiyle mümkündür."));button("▶  Sanal Makine Başlat",desktop,()->message("VM motoru henüz kurulu değil. USB aygıtı seçmek, USB bellekteki işletim sistemini başlatmaz. QEMU ve disk imajı entegrasyonu gerekiyor."));TextView h=new TextView(this);h.setText("Bağlı USB aygıtları");h.setTextColor(-1);h.setTextSize(19);h.setPadding(0,dp(16),0,dp(8));desktop.addView(h);devices=new LinearLayout(this);devices.setOrientation(1);desktop.addView(devices);desktop.setAlpha(0f);desktop.animate().alpha(1f).setDuration(450).start();refresh();}
 void refresh(){devices.removeAllViews();UsbManager usb=(UsbManager)getSystemService(USB_SERVICE);HashMap<String,UsbDevice> map=usb.getDeviceList();status.setText("Desktop Mode • "+map.size()+" USB aygıtı algılandı • VM henüz etkin değil");if(map.isEmpty()){button("USB aygıtı bulunamadı — USB belleği veya hub'ı bağla",devices,()->refresh());return;}for(UsbDevice d:map.values()){String name=d.getProductName()==null?"USB aygıtı":d.getProductName();button("▣  "+name+"\nVID "+d.getVendorId()+" · PID "+d.getProductId()+" · "+d.getInterfaceCount()+" arayüz",devices,()->new AlertDialog.Builder(this).setTitle(name).setMessage("Aygıt: "+d.getDeviceName()+"\nUSB bağlantısı algılandı. Bu listeleme diskin önyüklenebilir olduğunu doğrulamaz.\n\nUSB dosyalarını açmak için Android klasör seçicisini kullan.").setPositiveButton("Dosyaları Aç",(a,w)->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);try{startActivityForResult(i,30);}catch(Exception e){message(e.getMessage());}}).setNegativeButton("Kapat",null).show());}}
 void message(String s){new AlertDialog.Builder(this).setMessage(s).setPositiveButton("Tamam",null).show();}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==30&&result==RESULT_OK&&data!=null){try{android.net.Uri uri=data.getData();getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);message("Klasör erişimi verildi: "+uri+"\\nBu seçim henüz VM diskine bağlanmadı.");}catch(Exception e){message(e.getMessage());}}}
 @Override public void onBackPressed(){finish();}
}